(function() {
    "use strict";
    
    // 粒子类
    class Particle {
        constructor(x, y, type = 'trail') {
            this.x = x;
            this.y = y;
            this.type = type;
            
            // 根据类型设置不同的初始属性
            if (type === 'explosion') {
                this.size = Math.random() * 3 + 2;
                const angle = Math.random() * Math.PI * 2;
                const speed = Math.random() * 6 + 2;
                this.speedX = Math.cos(angle) * speed;
                this.speedY = Math.sin(angle) * speed;
                // 使用随机颜色
                const hue = Math.random() * 360;
                this.color = `hsla(${hue}, 100%, 60%, ${Math.random() * 0.5 + 0.5})`;
                this.life = 1;
                this.decay = Math.random() * 0.015 + 0.01;
                this.gravity = 0.1;
                // 添加轨迹历史记录
                this.history = [];
                this.maxHistory = 10;
            } else if (type === 'float') {
                this.size = Math.random() * 2 + 1;
                this.speedX = Math.random() * 1 - 0.5;
                this.speedY = Math.random() * 1 - 0.5;
                this.color = `rgba(255, 255, 255, ${Math.random() * 0.3 + 0.1})`;
                this.life = 1;
                this.decay = 0;
                this.gravity = 0;
            } else {
                this.size = Math.random() * 2 + 1;
                this.speedX = Math.random() * 1 - 0.5;
                this.speedY = Math.random() * 1 - 0.5;
                this.color = `rgba(255, 255, 255, ${Math.random() * 0.4 + 0.5})`;
                this.life = 1;
                this.decay = Math.random() * 0.03 + 0.02;
                this.gravity = 0;
            }
        }
        
        update() {
            // 保存当前位置到历史记录（仅用于爆炸粒子）
            if (this.type === 'explosion') {
                this.history.push({x: this.x, y: this.y});
                if (this.history.length > this.maxHistory) {
                    this.history.shift();
                }
            }
            
            this.x += this.speedX;
            this.speedY += this.gravity;
            this.y += this.speedY;
            this.life -= this.decay;
            
            // 爆炸粒子会有更大的速度衰减
            if (this.type === 'explosion') {
                this.speedX *= 0.96;
                this.speedY *= 0.96;
            }
            
            // 漂浮粒子边界检查
            if (this.type === 'float') {
                if (this.x < 0 || this.x > window.innerWidth) this.speedX *= -1;
                if (this.y < 0 || this.y > window.innerHeight) this.speedY *= -1;
            }
        }
        
        draw(ctx) {
            ctx.globalAlpha = this.life;
            ctx.fillStyle = this.color;
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
            ctx.fill();
            
            // 绘制拖尾（仅用于爆炸粒子）
            if (this.type === 'explosion' && this.history.length > 1) {
                ctx.beginPath();
                ctx.moveTo(this.history[0].x, this.history[0].y);
                for (let i = 1; i < this.history.length; i++) {
                    ctx.lineTo(this.history[i].x, this.history[i].y);
                }
                ctx.strokeStyle = this.color;
                ctx.lineWidth = this.size;
                ctx.stroke();
            }
            
            ctx.globalAlpha = 1;
        }
    }
    
    // 鼠标特效控制器
    class MouseEffect {
        constructor() {
            this.canvas = document.createElement('canvas');
            this.ctx = this.canvas.getContext('2d');
            this.particles = [];
            this.mouseX = 0;
            this.mouseY = 0;
            this.hue = 0;
            this.isRunning = false;
            
            this.init();
        }
        
        init() {
            // 设置画布样式
            this.canvas.style.position = 'fixed';
            this.canvas.style.top = '0';
            this.canvas.style.left = '0';
            this.canvas.style.width = '100%';
            this.canvas.style.height = '100%';
            this.canvas.style.pointerEvents = 'none';
            this.canvas.style.zIndex = '999999999';
            
            // 设置画布尺寸
            this.resize();
            
            // 添加到页面
            document.body.appendChild(this.canvas);
            
            // 初始化漂浮粒子（减少数量以提高性能）
            this.initFloatingParticles();
            
            // 监听事件
            window.addEventListener('resize', () => this.resize());
            window.addEventListener('mousemove', (e) => this.handleMouseMove(e));
            window.addEventListener('click', (e) => this.handleClick(e));
            
            // 开始动画循环
            this.animate();
        }
        
        resize() {
            this.canvas.width = window.innerWidth;
            this.canvas.height = window.innerHeight;
        }
        
        initFloatingParticles() {
            // 创建漂浮粒子（减少数量以提高性能）
            for (let i = 0; i < 30; i++) {
                const x = Math.random() * window.innerWidth;
                const y = Math.random() * window.innerHeight;
                this.particles.push(new Particle(x, y, 'float'));
            }
        }
        
        handleMouseMove(e) {
            this.mouseX = e.clientX;
            this.mouseY = e.clientY;
            
            // 减少拖尾粒子数量
            if (Math.random() > 0.8) { // 20%的概率产生拖尾粒子
                this.particles.push(new Particle(this.mouseX, this.mouseY, 'trail'));
            }
        }
        
        handleClick(e) {
            // 添加爆炸粒子（减少数量以提高性能）
            for (let i = 0; i < 40; i++) {
                this.particles.push(new Particle(e.clientX, e.clientY, 'explosion'));
            }
        }
        
        animate() {
            // 完全清除画布，而不是使用半透明覆盖
            this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
            
            // 更新和绘制粒子
            for (let i = this.particles.length - 1; i >= 0; i--) {
                this.particles[i].update();
                this.particles[i].draw(this.ctx);
                
                // 移除生命周期结束的粒子（漂浮粒子除外）
                if (this.particles[i].life <= 0 && this.particles[i].type !== 'float') {
                    this.particles.splice(i, 1);
                }
            }
            
            // 更新色相
            this.hue += 1;
            
            // 继续动画循环
            requestAnimationFrame(() => this.animate());
        }
    }
    
    // 初始化特效
    new MouseEffect();
})();
